var STORY = [{"n":1,"title":"Opening, meet Jeff","splash":false,"layout":"wide strip on top, a tall panel and a small panel side by side in the middle, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide, Top Third","desc":"Dawn over Durian City, a state of the art city like Makati. Glass towers catching the golden sunrise, wide avenues, colorful jeepneys driving along them, a few palm and durian trees along the street.","lines":[{"k":"cap","who":"","mod":"","t":"\"Durian City, Mindanao. 6:42 AM.\""},{"k":"sfx","who":"","mod":"giongo","t":"VROOOM, HONK HONK"},{"k":"sfx","who":"","mod":"gitaigo","t":"KINANG (the towers shining in the sunrise)"}],"rect":[3.0,3.0,94.0,19.98]},{"n":2,"size":"Tall, Middle Left","desc":"The gate of Durian City High School. Flag, painted sign, students trickling in, the modern skyline behind the school.","lines":[{"k":"sfx","who":"","mod":"giseigo","t":"DALDAL DALDAL (the chatter of the crowd)"},{"k":"sfx","who":"","mod":"giseigo","t":"BULONG BULONG (students whisper as Jeff walks by: \"That's the folklore guy.\")"},{"k":"sfx","who":"","mod":"giongo","t":"KRIIIK (the gate swinging)"}],"rect":[3.0,24.58,49.96,27.24]},{"n":3,"size":"Small, Middle Right","desc":"Close up: a necklace swinging against a blue uniform shirt. One tiny glint. No explanation.","lines":[{"k":"sfx","who":"","mod":"gitaigo","t":"KISLAP, TIBOK (a tiny glint and a tiny heartbeat, like the necklace is alive)"}],"rect":[55.36,24.58,41.64,27.24]},{"n":4,"size":"Large Low Angle, Bottom Half","desc":"Jeff walks toward the camera. Ube colored hair in the wind, one hand in his pocket, the other holding a thick book on Philippine folklore. Tall, lean, effortless.","lines":[{"k":"sfx","who":"","mod":"giongo","t":"SWISH (hair in the wind), TAP TAP (footsteps)"},{"k":"sfx","who":"","mod":"gitaigo","t":"KINTAB (a cool glow around Jeff)"},{"k":"cap","who":"","mod":"","t":"\"Jefferson Victorio. He looks like the cool one.\""},{"k":"cap","who":"","mod":"","t":"\"His classmates call him weird. He reads about ancient spirits for breakfast.\""}],"rect":[3.0,53.42,94.0,43.58]}]},{"n":2,"title":"Meet Hal","splash":false,"layout":"wide strip on top, two small panels, then a tall panel on the left and a large panel on the right.","note":"","panels":[{"n":1,"size":"Wide, Top","desc":"Behind Jeff, a tiny figure sprints through the crowd, a backpack bigger than he is.","lines":[{"k":"sfx","who":"","mod":"","t":"TAP TAP TAP TAP"}],"rect":[3.0,3.0,94.0,22.7]},{"n":2,"size":"Small","desc":"Jeff does not turn around. Small smirk.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Three. Two. One.\""}],"rect":[3.0,27.3,45.8,18.16]},{"n":3,"size":"Small","desc":"Hal crashes into Jeff's back. Glasses slide down his nose.","lines":[{"k":"sfx","who":"","mod":"","t":"THUD"},{"k":"say","who":"Hal","mod":"","t":"\"JEFF! Wait up!\""}],"rect":[51.2,27.3,45.8,18.16]},{"n":4,"size":"Tall, Left","desc":"Hal's face close up. Brown hair, round glasses, big eyes. He is very cute and very offended.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"You walked past the bakery again! I texted you six times!\""}],"rect":[3.0,47.06,36.64,49.94]},{"n":5,"size":"Large, Right","desc":"The height gap. Jeff looks down, Hal looks up, a paper bag of pandesal held high like a trophy.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"I got your favorite.\""},{"k":"say","who":"Jeff","mod":"","t":"\"You're a legend.\""},{"k":"cap","who":"","mod":"","t":"\"Hal Bautista. Loudest voice in any room.\""}],"rect":[42.04,47.06,54.96,49.94]}]},{"n":3,"title":"Meet Mel","splash":false,"layout":"wide strip on top, a tall panel on the left, three stacked small panels in the middle, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide, Top","desc":"Violin music drifts across the school grounds. Students stop on the stairs. Glowing musical notes weave through the air.","lines":[],"rect":[3.0,3.0,94.0,14.53]},{"n":2,"size":"Tall, Left","desc":"Mel on the school steps, eyes closed, long blonde hair over his shoulder, violin tucked under his chin. A very big, very gentle guy.","lines":[],"rect":[3.0,19.13,41.22,39.95]},{"n":3,"size":"Small","desc":"Jeff and Hal arrive at the bottom of the steps. Hal waves with the pandesal bag.","lines":[],"rect":[46.62,19.13,50.38,12.25]},{"n":4,"size":"Small","desc":"Mel opens his eyes and smiles without stopping the music.","lines":[],"rect":[46.62,32.98,50.38,12.25]},{"n":5,"size":"Small","desc":"Mel's bow slows, then stops.","lines":[{"k":"say","who":"Mel","mod":"","t":"\"Good morning. I made something new.\""}],"rect":[46.62,46.83,50.38,12.25]},{"n":6,"size":"Large, Bottom","desc":"The trio together. Hal has climbed two steps to reach Mel's shoulder height. Jeff leans on the railing with his book.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"It sounds like sunrise.\""},{"k":"say","who":"Hal","mod":"","t":"\"It sounds like pandesal.\""},{"k":"say","who":"Mel","mod":"","t":"\"Both are correct.\""},{"k":"cap","who":"","mod":"","t":"\"Mel Charlie Abaldado. The violin is the one thing that always makes sense to him.\""}],"rect":[3.0,60.68,94.0,36.32]}]},{"n":4,"title":"Meet Nikki","splash":false,"layout":"wide strip on top, a small panel and a tall panel, a large low angle panel in the middle, a medium panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide, Top","desc":"The gate opens. Wind. A group of girls in white blouses and skirts. No dialogue.","lines":[],"rect":[3.0,3.0,94.0,17.84]},{"n":2,"size":"Small","desc":"Hal freezes mid bite.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"...No.\""}],"rect":[3.0,22.44,45.8,23.19]},{"n":3,"size":"Tall","desc":"Students step aside, one after another, like a slow wave.","lines":[],"rect":[51.2,22.44,45.8,23.19]},{"n":4,"size":"Large Low Angle","desc":"Nikki walks forward, hair in the wind, her friends flanking her. She owns the sidewalk.","lines":[{"k":"cap","who":"","mod":"","t":"\"Nikki Sharon Legazpi. The most popular girl in school.\""}],"rect":[3.0,47.23,94.0,26.76]},{"n":5,"size":"Medium, Bottom","desc":"She stops in front of the trio. Smug.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"Look. The nerd, the giant, and the pocket edition.\""}],"rect":[3.0,75.59,94.0,21.41]}]},{"n":5,"title":"Nikki picks on Hal","splash":false,"layout":"small panel, wide panel, three small panels in a row, and a medium panel at the bottom.","note":"","panels":[{"n":1,"size":"Small","desc":"Hal bristles, finger raised.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"I am NOT a pocket edition!\""}],"rect":[3.0,3.0,27.48,19.98]},{"n":2,"size":"Wide","desc":"Nikki plucks his glasses off his face and holds them high. Her friends laugh.","lines":[],"rect":[32.88,3.0,64.12,19.98]},{"n":3,"size":"Small","desc":"Hal's blurry point of view: smears of color and shapes.","lines":[{"k":"say","who":"Hal","mod":"thought bubble","t":"\"I can't see anything\""}],"rect":[3.0,24.58,29.73,21.79]},{"n":4,"size":"Small","desc":"Hal jumping, fingertips short of the glasses.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"Aww. He can't even jump.\""}],"rect":[35.13,24.58,29.73,21.79]},{"n":5,"size":"Small","desc":"Mel lowers the violin, troubled.","lines":[{"k":"say","who":"Mel","mod":"","t":"\"Nikki, please. Those are his.\""}],"rect":[67.27,24.58,29.73,21.79]},{"n":6,"size":"Medium, Bottom","desc":"Jeff calm. His necklace swings once against his chest.","lines":[],"rect":[3.0,47.97,94.0,49.03]}]},{"n":6,"title":"Jeff steps in","splash":false,"layout":"wide panel, two medium panels, a small panel, and a large panel at the bottom that ends on a cliffhanger.","note":"","panels":[{"n":1,"size":"Wide","desc":"Jeff steps between Nikki and Hal. We see his back. Hal peeks out behind his arm.","lines":[],"rect":[3.0,3.0,94.0,16.06]},{"n":2,"size":"Medium","desc":"Jeff, steady.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Give them back.\""},{"k":"say","who":"Nikki","mod":"","t":"\"Make me.\""}],"rect":[3.0,20.66,45.8,19.62]},{"n":3,"size":"Medium","desc":"Jeff's smirk.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Do you ever get tired of being this predictable?\""},{"k":"say","who":"Nikki","mod":"","t":"\"Do you ever get tired of reading about ghosts?\""}],"rect":[51.2,20.66,45.8,19.62]},{"n":4,"size":"Small","desc":"Hal, from behind Jeff.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"They're not ghosts. It's folklore!\""},{"k":"say","who":"Mel","mod":"off panel","t":"\"It's technically mythology.\""}],"rect":[3.0,41.88,94.0,12.49]},{"n":5,"size":"Large","desc":"Nikki, smug and annoyed, flings Hal's glasses high over Jeff's head in a big arc, her arm swung out in a showy throw, with speed lines and a glint on the lenses. Her friends gasp.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"Fine. Go fetch.\""},{"k":"sfx","who":"","mod":"","t":"FLING"}],"rect":[3.0,55.97,94.0,41.03]}]},{"n":7,"title":"Jeff proves the point","splash":true,"layout":"one full page image.","note":"this is the page that shows Jeff is more than the weird folklore kid. Everyone else in the frame is in comic shock, Jeff is the only calm face. He looks cool, and for one moment the school sees it. Nikki's girls fall for him on the spot.","panels":[{"n":1,"size":"Full Page","desc":"Jeff, without even turning around, reaches up and catches the glasses between two fingers, calm and stylish. Dramatic angle from slightly below. Behind him Hal's eyes are huge, Mel's bow is frozen mid air, the students are frozen. Nikki's friends have their hands over their mouths and small hearts in their eyes. Leaves and dust float in a shaft of morning sun. Nikki's face is shocked.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Careful. Those are his.\""},{"k":"cap","who":"","mod":"tiny, bottom corner","t":"\"Jeff Victorio never starts a fight. He just never lets his friends stand alone.\""}],"rect":[3.0,3.0,94.0,94.0]}]},{"n":8,"title":"Aftermath","splash":false,"layout":"wide panel, two small panels, a medium panel, a small panel, and a wide panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"Silence. Then a long dreamy sigh from Nikki's friends, with tiny hearts floating up. The school bell rings.","lines":[{"k":"sfx","who":"","mod":"","t":"KRIIIIING"}],"rect":[3.0,3.0,94.0,18.3]},{"n":2,"size":"Small","desc":"Nikki's friends crowd around Jeff, starry eyed.","lines":[{"k":"say","who":"Nikki'S Friend","mod":"","t":"\"He caught it without even looking.\""},{"k":"say","who":"Nikki'S Other Friend","mod":"","t":"\"Okay, who knew?\""}],"rect":[3.0,22.9,45.8,20.58]},{"n":3,"size":"Small","desc":"Nikki, jaw tight, a stiff smile, snatches up her bag.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"Nice catch, Jeff. Finally, a use for all that ghost reading.\""}],"rect":[51.2,22.9,45.8,20.58]},{"n":4,"size":"Medium","desc":"Jeff gently puts the glasses back on Hal and straightens them.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"Thanks, Jeff.\""},{"k":"say","who":"Jeff","mod":"","t":"\"Don't mention it. Actually, mention it. I want credit.\""}],"rect":[3.0,45.08,55.76,27.45]},{"n":5,"size":"Small","desc":"Hal laughs through wet eyes.","lines":[],"rect":[61.16,45.08,35.84,27.45]},{"n":6,"size":"Wide, Bottom","desc":"The three walk toward the school, Mel playing softly. Far behind them, Nikki drags her friends along, and the friends keep looking back at Jeff. Nikki glances back for half a second.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"Whatever. Come on, girls.\""},{"k":"say","who":"Nikki'S Friend","mod":"","t":"\"Nik?\""},{"k":"say","who":"Nikki","mod":"","t":"\"Nothing.\""}],"rect":[3.0,74.13,94.0,22.87]}]},{"n":9,"title":"Homeroom, meet Sir Archie","splash":false,"layout":"wide panel on top, small panel, medium panel, small panel, large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"Homeroom. Ceiling fans, chalk dust, open windows with a view of the courtyard.","lines":[],"rect":[3.0,3.0,94.0,16.34]},{"n":2,"size":"Small","desc":"Sir Archie at the front. Cool, tall, muscular young teacher with white hair and rectangle glasses, tight buttoned shirt and a cardigan, a coffee thermos on the desk.","lines":[{"k":"cap","who":"","mod":"","t":"\"Mr. Archibald Oronies. Everyone calls him Sir Archie.\""}],"rect":[3.0,20.94,23.79,21.79]},{"n":3,"size":"Medium","desc":"Roll call, quick cuts of each of the four.","lines":[{"k":"say","who":"Sir Archie","mod":"","t":"\"Victorio?\""},{"k":"say","who":"Jeff","mod":"","t":"\"Present, sir.\""},{"k":"say","who":"Sir Archie","mod":"","t":"\"Bautista?\""},{"k":"say","who":"Hal","mod":"","t":"\"Here, Sir! Alive!\""},{"k":"say","who":"Sir Archie","mod":"","t":"\"Abaldado?\" MEL: \"Present.\""},{"k":"say","who":"Sir Archie","mod":"","t":"\"Legazpi?\" NIKKI: \"...Present.\""}],"rect":[29.19,20.94,41.63,21.79]},{"n":4,"size":"Small","desc":"Seats: the three in a row, Nikki one row ahead. She turns to glare at them.","lines":[],"rect":[73.21,20.94,23.79,21.79]},{"n":5,"size":"Large","desc":"Sir Archie writes on the board in big letters: SANGKAPULUAN.","lines":[],"rect":[3.0,44.34,94.0,52.66]}]},{"n":10,"title":"The lesson","splash":false,"layout":"medium panel, wide illustrated panel, small panel, medium panel, small panel, small panel.","note":"","panels":[{"n":1,"size":"Medium","desc":"Sir Archie.","lines":[{"k":"say","who":"Sir Archie","mod":"","t":"\"Before we start, a story. Long ago, our ancestors called these islands the Sangkapuluan.\""}],"rect":[3.0,3.0,36.64,31.13]},{"n":2,"size":"Wide","desc":"The islands drawn like an ancient map. Ten small points glow along the map.","lines":[{"k":"cap","who":"","mod":"","t":"\"Ten.\""}],"rect":[42.04,3.0,54.96,31.13]},{"n":3,"size":"Small","desc":"Hal whispers.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"Ten what?\""},{"k":"say","who":"Jeff","mod":"whispering back, eyes sparkling","t":"\"Agimats.\""}],"rect":[3.0,35.73,36.64,28.54]},{"n":4,"size":"Medium","desc":"Sir Archie.","lines":[{"k":"say","who":"Sir Archie","mod":"","t":"\"Every land has its Agimats. Charms with a power of their own. Ten are said to sleep in the Sangkapuluan, our islands.\""}],"rect":[42.04,35.73,54.96,28.54]},{"n":5,"size":"Small","desc":"Nikki, bored.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"So it's a fairy tale, Sir?\" The class laughs."},{"k":"say","who":"Sir Archie","mod":"","t":"\"Every fairy tale begins with someone who stopped listening.\""}],"rect":[3.0,65.87,45.8,31.13]},{"n":6,"size":"Small","desc":"Jeff's hand drifts to his collar and closes around the necklace.","lines":[],"rect":[51.2,65.87,45.8,31.13]}]},{"n":11,"title":"Detention","splash":false,"layout":"wide panel, three small panels, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"The bell. The class pours out.","lines":[],"rect":[3.0,3.0,94.0,16.34]},{"n":2,"size":"Small","desc":"Hal, walking beside Jeff.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"Do you think Agimats are real?\""}],"rect":[3.0,20.94,29.73,21.79]},{"n":3,"size":"Small","desc":"Jeff, cool.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Statistically unlikely.\""},{"k":"say","who":"Jeff","mod":"smaller","t":"\"But I want them to be.\""}],"rect":[35.13,20.94,29.73,21.79]},{"n":4,"size":"Small","desc":"Mel, shyly.","lines":[{"k":"say","who":"Mel","mod":"","t":"\"I think music could be one.\""}],"rect":[67.27,20.94,29.73,21.79]},{"n":5,"size":"Large","desc":"Sir Archie in the doorway, arms crossed. The four line up in front of him.","lines":[{"k":"say","who":"Sir Archie","mod":"","t":"\"I heard about the courtyard.\""},{"k":"say","who":"Nikki","mod":"","t":"\"He grabbed me!\""},{"k":"say","who":"Jeff","mod":"","t":"\"You swung first.\""},{"k":"say","who":"Sir Archie","mod":"","t":"\"Four sets of hands, one courtyard. The old storage room in the east building. All four of you. Today.\""}],"rect":[3.0,44.34,94.0,52.66]}]},{"n":12,"title":"The east building","splash":false,"layout":"two small panels, a wide panel, a small panel, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Small","desc":"Nikki, scandalized.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"Sir! I have a reputation!\""},{"k":"say","who":"Sir Archie","mod":"","t":"\"Then you'll finish faster.\""}],"rect":[3.0,3.0,45.8,14.27]},{"n":2,"size":"Small","desc":"Mel, hopeful.","lines":[{"k":"say","who":"Mel","mod":"","t":"\"Can I bring my violin?\""},{"k":"say","who":"Sir Archie","mod":"","t":"\"Gently.\""}],"rect":[51.2,3.0,45.8,14.27]},{"n":3,"size":"Wide","desc":"Late afternoon. The four walk across the campus toward a far corner. Nikki walks behind the others, alone.","lines":[],"rect":[3.0,18.87,94.0,14.27]},{"n":4,"size":"Small","desc":"Hal slows down and glances back at Nikki. She looks away quickly.","lines":[],"rect":[3.0,34.74,94.0,12.49]},{"n":5,"size":"Large","desc":"The old east building: cracked paint, vines, a rusted padlock. Sir Archie hands Jeff a key. His eyes rest on Jeff's collar for half a second too long. Then he leaves.","lines":[{"k":"say","who":"Sir Archie","mod":"","t":"\"Dust only. Don't touch the cabinets at the back.\""}],"rect":[3.0,48.83,94.0,48.17]}]},{"n":13,"title":"The storage room","splash":false,"layout":"large panel on top, two small panels in the middle, a wide panel at the bottom.","note":"","panels":[{"n":1,"size":"Large","desc":"The door creaks open. Slats of light, floating dust, stacked old desks, cracked blackboards, boxes, a standing fan with a bent blade.","lines":[],"rect":[3.0,3.0,94.0,32.69]},{"n":2,"size":"Small","desc":"Nikki, pinching her nose.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"It smells like grandma's closet.\""},{"k":"say","who":"Hal","mod":"","t":"\"That's the best closet.\""}],"rect":[3.0,37.29,45.8,21.79]},{"n":3,"size":"Small","desc":"Mel sneezes. A comic cloud of dust fills the panel.","lines":[{"k":"sfx","who":"","mod":"","t":"ACHOOOO"}],"rect":[51.2,37.29,45.8,21.79]},{"n":4,"size":"Wide","desc":"Jeff hands out gloves like a team captain. She smirks. She likes that.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Mel, top shelves. Hal, boxes. Nikki...\""},{"k":"say","who":"Nikki","mod":"","t":"\"I'm not touching anything.\""},{"k":"say","who":"Jeff","mod":"","t":"\"Great. You're supervisor.\""}],"rect":[3.0,60.68,94.0,36.32]}]},{"n":14,"title":"Cleaning, friendship beat","splash":false,"layout":"six panels in a grid, with the last one wider.","note":"","panels":[{"n":1,"size":"Small","desc":"Hal climbs a wobbling stack of boxes.","lines":[],"rect":[3.0,3.0,45.8,27.24]},{"n":2,"size":"Small","desc":"Mel lifts three desks at once. Hal, from the floor: \"Show off.\"","lines":[],"rect":[51.2,3.0,45.8,27.24]},{"n":3,"size":"Small","desc":"A box slides. Hal tumbles into a cloud of dust. Nikki laughs, then stops when she hears him cough, and looks guilty for a second.","lines":[],"rect":[3.0,31.84,45.8,27.24]},{"n":4,"size":"Small","desc":"Jeff finds an old textbook.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Whoa. A nineteen seventies Araling Panlipunan!\""},{"k":"say","who":"Hal","mod":"","t":"\"That's the nerdiest sentence you've ever said.\""}],"rect":[51.2,31.84,45.8,27.24]},{"n":5,"size":"Small","desc":"Mel hums while sweeping. The dust floats in rhythm with the tune.","lines":[],"rect":[3.0,60.68,36.64,36.32]},{"n":6,"size":"Wide","desc":"Sunset through the window. The room is clean. All four laugh at something. Even Nikki smiles, until Hal looks at her, and she turns away.","lines":[],"rect":[42.04,60.68,54.96,36.32]}]},{"n":15,"title":"The necklace reacts","splash":false,"layout":"small panel, close up panel, medium panel, two small panels, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Small","desc":"Jeff wipes his forehead. Under his collar, the necklace has a faint warm glow only the reader can see.","lines":[],"rect":[3.0,3.0,36.64,17.84]},{"n":2,"size":"Close Up","desc":"Jeff's hand closes around the pendant. His eyes widen. It is warm.","lines":[],"rect":[42.04,3.0,54.96,17.84]},{"n":3,"size":"Medium","desc":"He walks toward the back of the room. The glow grows brighter with every step.","lines":[],"rect":[3.0,22.44,94.0,16.06]},{"n":4,"size":"Small","desc":"Hal.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"Jeff? You okay?\""},{"k":"say","who":"Jeff","mod":"","t":"\"Yeah. I just thought I heard something humming.\""}],"rect":[3.0,40.1,45.8,14.27]},{"n":5,"size":"Small","desc":"Mel, head tilted.","lines":[{"k":"say","who":"Mel","mod":"","t":"\"I hear it too. It's a low note. Like a B flat.\""}],"rect":[51.2,40.1,45.8,14.27]},{"n":6,"size":"Large","desc":"All four turn to look at the same thing: the dark cabinet at the back of the room, the one Sir Archie warned about.","lines":[],"rect":[3.0,55.97,94.0,41.03]}]},{"n":16,"title":"The cabinet","splash":false,"layout":"wide panel on top, two small panels, a medium panel, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"The cabinet: old dark wood, carved with faded Baybayin patterns, a rusted padlock.","lines":[],"rect":[3.0,3.0,94.0,16.06]},{"n":2,"size":"Small","desc":"Nikki.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"Sir said don't touch it.\""},{"k":"say","who":"Hal","mod":"","t":"\"That's what everyone says right before the horror movie.\""}],"rect":[3.0,20.66,45.8,16.06]},{"n":3,"size":"Small","desc":"Jeff.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"We're not breaking anything. Just looking.\""},{"k":"say","who":"Mel","mod":"","t":"\"Looking is okay.\""}],"rect":[51.2,20.66,45.8,16.06]},{"n":4,"size":"Medium","desc":"Jeff steps close. The necklace flares. The rusted padlock crumbles to powder.","lines":[{"k":"sfx","who":"","mod":"","t":"CLINK"}],"rect":[3.0,38.31,94.0,17.84]},{"n":5,"size":"Large","desc":"The doors swing open. Shelves of old school things, and in the middle a bamboo tube wrapped in faded cloth, covered in glowing carved script.","lines":[],"rect":[3.0,57.75,94.0,39.25]}]},{"n":17,"title":"The tube","splash":false,"layout":"wide panel, close up panel, three small panels, a medium panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"The four gather in a half circle around the tube, now on a desk.","lines":[],"rect":[3.0,3.0,94.0,16.06]},{"n":2,"size":"Close Up","desc":"The carved script. Faint golden lines pulse inside the grooves.","lines":[],"rect":[3.0,20.66,94.0,17.84]},{"n":3,"size":"Small","desc":"Hal.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"Is that... writing?\""},{"k":"say","who":"Jeff","mod":"","t":"\"Baybayin. The old script, before the Spanish. I've been studying it for fun.\""}],"rect":[3.0,40.1,29.73,16.06]},{"n":4,"size":"Small","desc":"Nikki.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"Of course you have.\""}],"rect":[35.13,40.1,29.73,16.06]},{"n":5,"size":"Small","desc":"Mel.","lines":[{"k":"say","who":"Mel","mod":"","t":"\"The hum is coming from it.\""}],"rect":[67.27,40.1,29.73,16.06]},{"n":6,"size":"Medium","desc":"Hal tugging Jeff's sleeve.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"Maybe we should call Sir Archie?\""},{"k":"say","who":"Jeff","mod":"","t":"\"Just one line. I can read some of it.\""}],"rect":[3.0,57.75,94.0,39.25]}]},{"n":18,"title":"Hiraya","splash":false,"layout":"wide panel, small panel, small panel, medium panel, two small panels.","note":"","panels":[{"n":1,"size":"Wide","desc":"Jeff holds the tube. The others lean in. Orange sunlight on all four faces.","lines":[],"rect":[3.0,3.0,94.0,22.3]},{"n":2,"size":"Small","desc":"His finger traces the first glyph.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Hi...\""}],"rect":[3.0,26.9,45.8,15.61]},{"n":3,"size":"Small","desc":"The second.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"...ra...\""}],"rect":[51.2,26.9,45.8,15.61]},{"n":4,"size":"Medium","desc":"Jeff.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Hiraya. It says hiraya manawari. It means, may your dreams come true.\""},{"k":"say","who":"Nikki","mod":"quietly","t":"\"That's kind of nice.\""}],"rect":[3.0,44.11,94.0,28.99]},{"n":5,"size":"Small","desc":"Hal.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"So it's a fortune cookie.\""}],"rect":[3.0,74.7,45.8,22.3]},{"n":6,"size":"Small","desc":"Jeff, eyes scanning ahead.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"There's more. A whole verse.\""}],"rect":[51.2,74.7,45.8,22.3]}]},{"n":19,"title":"The dare","splash":false,"layout":"medium panel, two small panels, a medium panel, a small panel, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Medium","desc":"All three look at Jeff.","lines":[],"rect":[3.0,3.0,94.0,16.06]},{"n":2,"size":"Small","desc":"Nikki, arms crossed.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"Go on. Unless the weirdo's scared.\""}],"rect":[3.0,20.66,45.8,12.49]},{"n":3,"size":"Small","desc":"Jeff.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"I'm not scared. I'm thorough.\""}],"rect":[51.2,20.66,45.8,12.49]},{"n":4,"size":"Medium","desc":"Mel lifts his violin.","lines":[{"k":"say","who":"Mel","mod":"","t":"\"I'll give it a tune. Every story needs a soundtrack.\""}],"rect":[3.0,34.74,59.54,16.06]},{"n":5,"size":"Small","desc":"Hal grips a fistful of Jeff's shirt.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"If we die, I'm haunting all of you.\""}],"rect":[64.94,34.74,32.06,16.06]},{"n":6,"size":"Large","desc":"Jeff inhales. Lifts the tube. Total silence. The glow in the grooves grows.","lines":[],"rect":[3.0,52.4,94.0,44.6]}]},{"n":20,"title":"The reading","splash":false,"layout":"large panel on top, four small panels, a wide panel at the bottom.","note":"","panels":[{"n":1,"size":"Large","desc":"Jeff reads aloud. Ribbons of golden Baybayin script lift from the tube and curl around him.","lines":[{"k":"cap","who":"","mod":"","t":"\"(Baybayin lines to be written and verified by a Baybayin source before print.)\""}],"rect":[3.0,3.0,94.0,30.87]},{"n":2,"size":"Small","desc":"Mel's violin joins, matching the rhythm of the words.","lines":[],"rect":[3.0,35.47,21.7,21.79]},{"n":3,"size":"Small","desc":"Hal's glasses reflect gold light. His mouth is open.","lines":[],"rect":[27.1,35.47,21.7,21.79]},{"n":4,"size":"Small","desc":"Nikki steps back. Her hair lifts in a wind that has no source.","lines":[],"rect":[51.2,35.47,21.7,21.79]},{"n":5,"size":"Small","desc":"The necklace flares bright. The chain floats up off Jeff's neck.","lines":[],"rect":[75.3,35.47,21.7,21.79]},{"n":6,"size":"Wide","desc":"The whole room glows. A low hum swells.","lines":[{"k":"sfx","who":"","mod":"","t":"HUUUUUUMMMMM"}],"rect":[3.0,58.86,94.0,38.14]}]},{"n":21,"title":"It pulls them","splash":false,"layout":"wide panel, two small panels, a medium panel, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"The room shakes. Boxes rattle, dust whirls, the old fan spins on its own.","lines":[],"rect":[3.0,3.0,94.0,14.27]},{"n":2,"size":"Small","desc":"Hal.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"JEFF, STOP!\""},{"k":"say","who":"Jeff","mod":"","t":"\"I can't! The words are pulling me!\""}],"rect":[3.0,18.87,45.8,16.06]},{"n":3,"size":"Small","desc":"Mel, wide eyed, still playing. He can't stop either.","lines":[],"rect":[51.2,18.87,45.8,16.06]},{"n":4,"size":"Medium","desc":"Nikki grabs Hal's arm without thinking. Hal grabs back.","lines":[],"rect":[3.0,36.53,94.0,17.84]},{"n":5,"size":"Large","desc":"Ribbons of golden script wrap around all four of them.","lines":[],"rect":[3.0,55.97,94.0,41.03]}]},{"n":22,"title":"Four faces","splash":false,"layout":"four tall vertical strips side by side across the top two thirds, one wide panel at the bottom.","note":"","panels":[{"n":1,"size":"Tall","desc":"Jeff, determined, eyes forward.","lines":[],"rect":[3.0,3.0,21.7,60.98]},{"n":2,"size":"Tall","desc":"Hal, terrified, clutching his glasses.","lines":[],"rect":[27.1,3.0,21.7,60.98]},{"n":3,"size":"Tall","desc":"Mel, amazed, violin pressed to his chest.","lines":[],"rect":[51.2,3.0,21.7,60.98]},{"n":4,"size":"Tall","desc":"Nikki, scared, eyes squeezed shut.","lines":[],"rect":[75.3,3.0,21.7,60.98]},{"n":5,"size":"Wide","desc":"Outside the window the sky bends like glass. The school windows crack with golden light.","lines":[],"rect":[3.0,65.58,94.0,31.42]}]},{"n":23,"title":"The last word","splash":false,"layout":"small panel, a thin black strip, a small panel, a large panel.","note":"","panels":[{"n":1,"size":"Small","desc":"Jeff, whispering.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"...manawari.\""}],"rect":[3.0,3.0,94.0,17.84]},{"n":2,"size":"Thin Strip, Full Width","desc":"Pure black. Silence.","lines":[],"rect":[3.0,22.44,94.0,5.35]},{"n":3,"size":"Small","desc":"A single sound.","lines":[{"k":"sfx","who":"","mod":"","t":"..."}],"rect":[3.0,29.39,94.0,17.84]},{"n":4,"size":"Large","desc":"White flash fills the panel. The ribbons form a spiral.","lines":[{"k":"sfx","who":"","mod":"","t":"KRAAATHOOOOM"}],"rect":[3.0,48.83,94.0,48.17]}]},{"n":24,"title":"The fall","splash":false,"layout":"wide panel, three small panels, a medium panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"A tunnel of light. Chalkboards, desks, and school fragments float past. The four are falling.","lines":[],"rect":[3.0,3.0,94.0,19.98]},{"n":2,"size":"Small","desc":"Hal, screaming. His glasses float off his nose but stay on by a miracle.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"AAAAAAAAAAAH!\""}],"rect":[3.0,24.58,29.73,19.98]},{"n":3,"size":"Small","desc":"Mel curls around his violin to protect it.","lines":[],"rect":[35.13,24.58,29.73,19.98]},{"n":4,"size":"Small","desc":"Nikki screaming. Then she sees Hal's hand holding hers. She stares at it.","lines":[],"rect":[67.27,24.58,29.73,19.98]},{"n":5,"size":"Medium","desc":"Jeff reaches for all of them.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Hold on to each other!\""}],"rect":[3.0,46.15,94.0,50.85]}]},{"n":25,"title":"Years","splash":false,"layout":"large panel on top, three small panels, a wide panel at the bottom.","note":"","panels":[{"n":1,"size":"Large","desc":"Glowing numbers rush past like falling stars: 2026, 1900, 1521, 1200. They settle on 1003.","lines":[],"rect":[3.0,3.0,94.0,32.69]},{"n":2,"size":"Small","desc":"Jeff, to himself.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"The year... it's going backward.\""}],"rect":[3.0,37.29,29.73,19.98]},{"n":3,"size":"Small","desc":"Hal, green faced.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"I'M GOING TO THROW UP.\""}],"rect":[35.13,37.29,29.73,19.98]},{"n":4,"size":"Small","desc":"Mel.","lines":[{"k":"say","who":"Mel","mod":"","t":"\"Please don't throw up on the violin.\""}],"rect":[67.27,37.29,29.73,19.98]},{"n":5,"size":"Wide","desc":"At the end of the tunnel: sunlight, blue sky, and far below, a river.","lines":[],"rect":[3.0,58.86,94.0,38.14]}]},{"n":26,"title":"Out of the sky","splash":false,"layout":"wide panel, two small panels, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"The four burst out of the sky above a river delta, trailing golden ribbons.","lines":[],"rect":[3.0,3.0,94.0,21.79]},{"n":2,"size":"Small","desc":"Below: wooden boats, small people looking up.","lines":[],"rect":[3.0,26.39,45.8,18.16]},{"n":3,"size":"Small","desc":"Nikki.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"THERE'S WATER!\""},{"k":"say","who":"Jeff","mod":"","t":"\"That's good!\""},{"k":"say","who":"Hal","mod":"","t":"\"I CAN'T SWIM VERY WELL!\""},{"k":"say","who":"Jeff","mod":"","t":"\"Then hold your breath!\""}],"rect":[51.2,26.39,45.8,18.16]},{"n":4,"size":"Large","desc":"Jeff dives to catch Hal and grabs his hand.","lines":[],"rect":[3.0,46.15,94.0,50.85]}]},{"n":27,"title":"Splash","splash":false,"layout":"one tall panel on the left, four stacked small panels on the right.","note":"","panels":[{"n":1,"size":"Tall","desc":"The impact. A huge splash on the river. Birds scatter.","lines":[{"k":"sfx","who":"","mod":"","t":"SPLOOOSH"}],"rect":[3.0,3.0,41.22,94.0]},{"n":2,"size":"Small","desc":"Underwater: bubbles. Mel's blonde hair floats like seaweed. He holds the violin to his chest.","lines":[],"rect":[46.62,3.0,50.38,22.3]},{"n":3,"size":"Small","desc":"Hal sinking, eyes wide.","lines":[],"rect":[46.62,26.9,50.38,22.3]},{"n":4,"size":"Small","desc":"Jeff swims, catches Hal's drifting glasses.","lines":[],"rect":[46.62,50.8,50.38,22.3]},{"n":5,"size":"Small","desc":"Nikki reaches for Hal's other hand and pulls him up with Jeff.","lines":[],"rect":[46.62,74.7,50.38,22.3]}]},{"n":28,"title":"Surface","splash":false,"layout":"wide panel, three small panels, a medium panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"Four heads pop up on a calm river near a mangrove bank. Early morning light.","lines":[],"rect":[3.0,3.0,94.0,19.98]},{"n":2,"size":"Small","desc":"Hal, coughing.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"I'm alive! I'm alive!\""}],"rect":[3.0,24.58,29.73,19.98]},{"n":3,"size":"Small","desc":"Nikki, soaked and furious at her hair. Hal blinks, surprised.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"My hair!\""},{"k":"say","who":"Nikki","mod":"quietly","t":"\"Hal. Are you okay?\""}],"rect":[35.13,24.58,29.73,19.98]},{"n":4,"size":"Small","desc":"Mel holds the violin above the water like a trophy.","lines":[{"k":"say","who":"Mel","mod":"","t":"\"She's okay. We're all okay.\""}],"rect":[67.27,24.58,29.73,19.98]},{"n":5,"size":"Medium","desc":"Jeff, dripping. The necklace clings to his chest and the glow fades.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Guys... look.\""}],"rect":[3.0,46.15,94.0,50.85]}]},{"n":29,"title":"First contact","splash":false,"layout":"wide panel, two small panels, a medium panel, a small panel, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"They crawl onto a muddy bank beside a wooden pier. A child with a fishing net stares at them.","lines":[],"rect":[3.0,3.0,94.0,16.06]},{"n":2,"size":"Small","desc":"The child's point of view: four strangers in strange wet clothes, one with purple hair.","lines":[],"rect":[3.0,20.66,45.8,14.27]},{"n":3,"size":"Small","desc":"The child shouts and runs. (Spoken in an old tongue, shown in brackets.)","lines":[{"k":"say","who":"Child","mod":"","t":"[Strangers! They fell from the sky!]"}],"rect":[51.2,20.66,45.8,14.27]},{"n":4,"size":"Medium","desc":"Hal.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"Did he just say sky?\""},{"k":"say","who":"Jeff","mod":"","t":"\"I understood him. It's Bisaya, but with words nobody uses anymore.\""},{"k":"say","who":"Hal","mod":"","t":"\"I only understood half of that.\""}],"rect":[3.0,36.53,59.54,17.84]},{"n":5,"size":"Small","desc":"Nikki.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"Okay. Where are we?\""}],"rect":[64.94,36.53,32.06,17.84]},{"n":6,"size":"Large","desc":"They climb up the bank toward the pier, mud on their knees, Mel pulling Hal.","lines":[],"rect":[3.0,55.97,94.0,41.03]}]},{"n":30,"title":"The top of the hill","splash":false,"layout":"three small panels, a thin wide panel, a small panel, a medium panel.","note":"","panels":[{"n":1,"size":"Small","desc":"Hal slips. Mel pulls him up by the backpack.","lines":[],"rect":[3.0,3.0,29.73,21.79]},{"n":2,"size":"Small","desc":"Off panel sounds drift in: gongs, voices, rushing water, a hundred things at once.","lines":[],"rect":[35.13,3.0,29.73,21.79]},{"n":3,"size":"Small","desc":"Jeff reaches the top first. The wind lifts his hair.","lines":[],"rect":[67.27,3.0,29.73,21.79]},{"n":4,"size":"Thin Wide","desc":"Close up of Jeff's eyes. Gold light in them.","lines":[],"rect":[3.0,26.39,94.0,9.08]},{"n":5,"size":"Small","desc":"Jeff's thought:","lines":[{"k":"cap","who":"","mod":"","t":"\"This isn't our school. This isn't our city. This isn't even our century.\""}],"rect":[3.0,37.07,36.64,59.93]},{"n":6,"size":"Medium","desc":"Hal from below.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"Jeff? What do you see?\""}],"rect":[42.04,37.07,54.96,59.93]}]},{"n":31,"title":"Butuan","splash":true,"layout":"one full page image.","note":"this is the biggest image in the chapter. It is the answer to the whole premise. No dialogue.","panels":[{"n":1,"size":"Full Page","desc":"The grand reveal. A huge river port at dawn. Dozens of plank boats with striped sails, joined with wooden pegs, crowd the water. Stilt houses line the banks. People wear gold ornaments that flash in the early sun. Foreign trade ships with different sails sit further out. A carved wooden hall with a gold decorated roof sits on the hill in the distance. In the foreground, small, four silhouettes stand at the top of the bank: a tall one with spiky hair, a short one with glasses, a big one holding a violin, a girl with her wet hair blowing.","lines":[{"k":"cap","who":"","mod":"","t":"\"Butuan. The year 1003.\""}],"rect":[3.0,3.0,94.0,94.0]}]},{"n":32,"title":"Reaction","splash":false,"layout":"wide panel, three small panels, a medium panel, a small panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"From behind, the four look out at the harbor. Hal's mouth hangs open.","lines":[],"rect":[3.0,3.0,94.0,23.28]},{"n":2,"size":"Small","desc":"Hal.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"Okay. That's a lot of boats.\""}],"rect":[3.0,27.88,29.73,20.95]},{"n":3,"size":"Small","desc":"Jeff, nerd mode.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Those are balangay. Plank boats joined with wooden pegs. No nails.\""}],"rect":[35.13,27.88,29.73,20.95]},{"n":4,"size":"Small","desc":"Nikki.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"STOP explaining, nerd! Where are we?\""},{"k":"say","who":"Nikki","mod":"smaller","t":"\"...are we dead?\""}],"rect":[67.27,27.88,29.73,20.95]},{"n":5,"size":"Medium","desc":"Jeff, calm and steady, for once the one who knows what is going on.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Not dead. Just very, very early.\""}],"rect":[3.0,50.44,59.54,46.56]},{"n":6,"size":"Small","desc":"Hal.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"BACK IN TIME?! I have a quiz tomorrow!\""}],"rect":[64.94,50.44,32.06,46.56]}]},{"n":33,"title":"Noticed","splash":false,"layout":"wide panel, two small panels, a medium panel, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"The market. People stop one by one and turn to look.","lines":[],"rect":[3.0,3.0,94.0,17.84]},{"n":2,"size":"Small","desc":"Whispers, shown in brackets: [Their clothes.] [Their hair.] A woman points at Jeff's purple hair.","lines":[],"rect":[3.0,22.44,45.8,16.06]},{"n":3,"size":"Small","desc":"The child returns, pulling a group of warriors by the hand.","lines":[],"rect":[51.2,22.44,45.8,16.06]},{"n":4,"size":"Medium","desc":"Warriors with bronze tipped spears, woven wraps, and gold armbands. (Costume details are DRAFT, to be researched.)","lines":[],"rect":[3.0,40.1,94.0,19.62]},{"n":5,"size":"Large","desc":"The warriors surround the four. Spears lowered. Everyone freezes.","lines":[],"rect":[3.0,61.32,94.0,35.68]}]},{"n":34,"title":"Tense, and the first misunderstanding","splash":false,"layout":"small panel, medium panel, two small panels, a small panel, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Small","desc":"Hal, behind Jeff.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"Jeff. Spears.\""}],"rect":[3.0,3.0,32.06,19.62]},{"n":2,"size":"Medium","desc":"Jeff raises his hands slowly, cool as ever, and speaks slowly in Bisaya (shown here in English).","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Good morning! We are friends!\""},{"k":"cap","who":"","mod":"","t":"\"(Jeff used the modern Bisaya word for 'friends'. In the old tongue it sounds like their word for 'fish bait'.)\""}],"rect":[37.46,3.0,59.54,19.62]},{"n":3,"size":"Small","desc":"The lead warrior, frowning.","lines":[{"k":"say","who":"Warrior","mod":"","t":"[Bait? He says they are bait?]"}],"rect":[3.0,24.22,45.8,14.27]},{"n":4,"size":"Small","desc":"A second warrior eyes them up and down.","lines":[{"k":"say","who":"Warrior 2","mod":"","t":"[Bait for what? For us?]"},{"k":"say","who":"Hal","mod":"","t":"\"Why are they looking at us like lunch?\""}],"rect":[51.2,24.22,45.8,14.27]},{"n":5,"size":"Small","desc":"Nikki hides behind Mel, voice tiny.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"Mel. Do something.\""},{"k":"say","who":"Mel","mod":"","t":"\"What can I do?\""},{"k":"say","who":"Nikki","mod":"","t":"\"ANYTHING!\""}],"rect":[3.0,40.1,94.0,12.49]},{"n":6,"size":"Large","desc":"Mel looks at the violin. Looks at the spears. A small, brave smile.","lines":[],"rect":[3.0,54.18,94.0,42.82]}]},{"n":35,"title":"Mel's music","splash":false,"layout":"large panel on top, three small panels, a medium panel, a wide panel at the bottom.","note":"","panels":[{"n":1,"size":"Large","desc":"Mel steps forward and raises the violin. A soft, gentle melody. Glowing notes ripple outward through the crowd like water.","lines":[],"rect":[3.0,3.0,94.0,30.33]},{"n":2,"size":"Small","desc":"The warriors flinch, then freeze and listen.","lines":[],"rect":[3.0,34.93,29.73,16.06]},{"n":3,"size":"Small","desc":"The child lowers his net, enchanted.","lines":[],"rect":[35.13,34.93,29.73,16.06]},{"n":4,"size":"Small","desc":"A woman with a basket on her head stops walking.","lines":[],"rect":[67.27,34.93,29.73,16.06]},{"n":5,"size":"Medium","desc":"Jeff glances at Mel, impressed.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Mel. That's it.\""}],"rect":[3.0,52.58,94.0,17.84]},{"n":6,"size":"Wide","desc":"The circle of spears slowly lowers. A bubble of calm spreads outward. Notes drift toward the harbor.","lines":[],"rect":[3.0,72.02,94.0,24.98]}]},{"n":36,"title":"Celebrity Hal","splash":false,"layout":"wide panel, two small panels, a small panel, a medium panel, a small panel.","note":"","panels":[{"n":1,"size":"Wide","desc":"The crowd gathers. Children creep closer to the foreigners.","lines":[],"rect":[3.0,3.0,94.0,19.98]},{"n":2,"size":"Small","desc":"A child touches Hal's glasses. Hal freezes.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"Jeff. A child is touching my face.\""}],"rect":[3.0,24.58,45.8,14.53]},{"n":3,"size":"Small","desc":"The child laughs.","lines":[{"k":"say","who":"Child","mod":"","t":"[Glass eyes!]"}],"rect":[51.2,24.58,45.8,14.53]},{"n":4,"size":"Small","desc":"Nikki giggles. Hal sees. She turns away quickly.","lines":[],"rect":[3.0,40.7,23.79,56.3]},{"n":5,"size":"Medium","desc":"Jeff, grinning.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Hal, you're a celebrity.\""},{"k":"say","who":"Hal","mod":"","t":"\"I don't want this.\""}],"rect":[29.19,40.7,41.63,56.3]},{"n":6,"size":"Small","desc":"The lead warrior, an older man with a gold armband, steps in.","lines":[{"k":"say","who":"Warrior","mod":"","t":"[Enough. They will go to the Rajah.]"}],"rect":[73.21,40.7,23.79,56.3]}]},{"n":37,"title":"Through the market","splash":false,"layout":"medium panel, a wide panel, two small panels, a small panel, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Medium","desc":"The warrior points up the hill.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"He says the Rajah. I think we're being invited.\""},{"k":"say","who":"Hal","mod":"","t":"\"Invited or arrested?\""},{"k":"say","who":"Jeff","mod":"","t":"\"Same room, different mood.\""}],"rect":[3.0,3.0,94.0,15.77]},{"n":2,"size":"Wide","desc":"They walk through the market: stalls of gold work, woven cloth, fruit, and pottery from far away lands.","lines":[],"rect":[3.0,20.37,94.0,14.02]},{"n":3,"size":"Small","desc":"Hal gawks at a goldsmith pouring molten gold from a clay crucible.","lines":[],"rect":[3.0,35.98,45.8,14.02]},{"n":4,"size":"Small","desc":"Mel whispers, staring at a stall with bronze gongs.","lines":[{"k":"say","who":"Mel","mod":"","t":"\"Those gongs.\""}],"rect":[51.2,35.98,45.8,14.02]},{"n":5,"size":"Small","desc":"Nikki sees a girl her age selling cloth. The girl looks at Nikki's white blouse with open curiosity. Nikki, for once, doesn't look away.","lines":[],"rect":[3.0,51.6,94.0,12.26]},{"n":6,"size":"Large","desc":"Trade boats unload goods from far away. Jeff, glowing like a kid.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"That's a real trade port. This is the golden age.\""},{"k":"say","who":"Hal","mod":"","t":"\"Of what?\""},{"k":"say","who":"Jeff","mod":"","t":"\"Of everything!\""}],"rect":[3.0,65.46,94.0,31.54]}]},{"n":38,"title":"The Rajah's hall","splash":false,"layout":"wide panel, two small panels, a medium panel, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"Up the hill. A wooden hall with carved posts and a gold decorated roof.","lines":[],"rect":[3.0,3.0,94.0,17.84]},{"n":2,"size":"Small","desc":"Guards. Carved wood. Incense smoke at the door.","lines":[],"rect":[3.0,22.44,45.8,16.06]},{"n":3,"size":"Small","desc":"Hal, whispering.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"Do we bow?\""},{"k":"say","who":"Mel","mod":"","t":"\"I'll bow twice.\""}],"rect":[51.2,22.44,45.8,16.06]},{"n":4,"size":"Medium","desc":"Nikki. She bows, fast.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"I'm not bowing to...\""},{"k":"say","who":"Jeff","mod":"","t":"\"Nikki. Bow.\""}],"rect":[3.0,40.1,94.0,19.62]},{"n":5,"size":"Large","desc":"The Rajah on the dais. Gold armbands, a calm and severe face. Beside him stands an elder advisor with a staff. (The Rajah is based on Kiling, the ruler named in Chinese records of this period. Design and personality are DRAFT.)","lines":[],"rect":[3.0,61.32,94.0,35.68]}]},{"n":39,"title":"Audience, and the second misunderstanding","splash":false,"layout":"wide panel, two small panels, a medium panel, a small panel, a small panel.","note":"","panels":[{"n":1,"size":"Wide","desc":"The four kneel in a line, wet, muddy, in school uniforms. A strong contrast with the gold hall.","lines":[],"rect":[3.0,3.0,94.0,17.84]},{"n":2,"size":"Small","desc":"The Rajah.","lines":[{"k":"say","who":"Rajah","mod":"","t":"[Who are you, who arrive on my river with no boat?]"}],"rect":[3.0,22.44,45.8,14.27]},{"n":3,"size":"Small","desc":"Jeff, catching the meaning.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"He's asking who we are.\""}],"rect":[51.2,22.44,45.8,14.27]},{"n":4,"size":"Medium","desc":"Jeff stands halfway and speaks in slow, careful Bisaya (shown in English).","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"I am Jeff. We are only visitors.\""},{"k":"cap","who":"","mod":"","t":"\"(Jeff's word for 'visitors' is now their word for 'ghosts'. Words change a lot in a thousand years.)\""}],"rect":[3.0,38.31,94.0,17.84]},{"n":5,"size":"Small","desc":"The court erupts. A man drops his basket.","lines":[{"k":"say","who":"Court","mod":"","t":"[GHOSTS!]"},{"k":"say","who":"Hal","mod":"","t":"\"What did you say?!\""},{"k":"say","who":"Jeff","mod":"","t":"\"I said visitors!\""}],"rect":[3.0,57.75,45.8,39.25]},{"n":6,"size":"Small","desc":"The Rajah is unbothered, eyes fixed on Jeff's chest. The elder leans in and whispers to him.","lines":[{"k":"say","who":"Elder","mod":"","t":"[The boy means guests. The word has moved with the years.]"}],"rect":[51.2,57.75,45.8,39.25]}]},{"n":40,"title":"The necklace","splash":false,"layout":"small panel, wide panel, small panel, close up panel, small panel, large panel at the bottom.","note":"","panels":[{"n":1,"size":"Small","desc":"The Rajah rises slowly.","lines":[],"rect":[3.0,3.0,94.0,12.26]},{"n":2,"size":"Wide","desc":"The court gasps. The elder advisor's staff drops to the floor.","lines":[{"k":"sfx","who":"","mod":"","t":"CLACK"}],"rect":[3.0,16.86,94.0,14.02]},{"n":3,"size":"Small","desc":"The elder.","lines":[{"k":"say","who":"Elder","mod":"","t":"[That... is one of the ten.]"}],"rect":[3.0,32.48,41.64,15.77]},{"n":4,"size":"Close Up","desc":"Jeff's necklace. A thread of gold light moves inside it.","lines":[],"rect":[47.04,32.48,49.96,15.77]},{"n":5,"size":"Small","desc":"Jeff.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"What do you mean, one of the ten?\""}],"rect":[3.0,49.85,94.0,10.51]},{"n":6,"size":"Large","desc":"All four look at the necklace.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"Jeff. What did your dad give you?\""},{"k":"say","who":"Jeff","mod":"","t":"\"A necklace. He said to keep it safe.\""}],"rect":[3.0,61.96,94.0,35.04]}]},{"n":41,"title":"Guests, maybe","splash":false,"layout":"wide panel, small panel, medium panel, two small panels, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"Uproar in the hall. The guards step forward again.","lines":[],"rect":[3.0,3.0,94.0,15.77]},{"n":2,"size":"Small","desc":"The Rajah raises one hand. Silence.","lines":[],"rect":[3.0,20.37,94.0,12.26]},{"n":3,"size":"Medium","desc":"The Rajah.","lines":[{"k":"say","who":"Rajah","mod":"","t":"[Bring them food and dry cloth. They are my guests until I say otherwise.]"},{"k":"say","who":"Jeff","mod":"","t":"\"We're guests. Maybe.\""}],"rect":[3.0,34.23,94.0,15.77]},{"n":4,"size":"Small","desc":"Hal.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"That's the nicest way I've heard 'prisoner' said.\""}],"rect":[3.0,51.6,45.8,14.02]},{"n":5,"size":"Small","desc":"The elder whispers to the Rajah. Both look at Jeff.","lines":[],"rect":[51.2,51.6,45.8,14.02]},{"n":6,"size":"Large","desc":"Guards lead the four out. Jeff looks back. The elder's eyes follow him.","lines":[],"rect":[3.0,67.22,94.0,29.78]}]},{"n":42,"title":"Borrowed clothes","splash":false,"layout":"wide panel, three small panels, a small panel, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"Evening. A guest house on stilts over the river. Torches, a gold sunset on the water.","lines":[],"rect":[3.0,3.0,94.0,16.06]},{"n":2,"size":"Small","desc":"The four wear borrowed woven clothes. Hal's is far too big.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"I look like a very sad tablecloth.\""}],"rect":[3.0,20.66,29.73,16.06]},{"n":3,"size":"Small","desc":"Mel holds up a tiny wrap, deeply sorry. A servant hurries in with a bigger cloth.","lines":[{"k":"say","who":"Mel","mod":"","t":"\"This will not cover me.\""}],"rect":[35.13,20.66,29.73,16.06]},{"n":4,"size":"Small","desc":"Nikki steps out in a woven skirt, hair tied up. The guys stare.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"WHAT.\""}],"rect":[67.27,20.66,29.73,16.06]},{"n":5,"size":"Small","desc":"Jeff, quickly looking away.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Nothing. You look... ready.\""}],"rect":[3.0,38.31,94.0,12.49]},{"n":6,"size":"Large","desc":"The four sit on the floor around grilled fish, rice, and fruit. Steam. Soft light. For a moment they just eat.","lines":[],"rect":[3.0,52.4,94.0,44.6]}]},{"n":43,"title":"Home","splash":false,"layout":"wide panel, three small panels, a medium panel, a small panel.","note":"","panels":[{"n":1,"size":"Wide","desc":"The four sitting at the edge of the veranda. Lanterns float on the river below.","lines":[],"rect":[3.0,3.0,94.0,23.28]},{"n":2,"size":"Small","desc":"Hal.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"So we just read it again and go home, right?\""}],"rect":[3.0,27.88,29.73,20.95]},{"n":3,"size":"Small","desc":"Jeff.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"The tube. Did anyone grab it?\""}],"rect":[35.13,27.88,29.73,20.95]},{"n":4,"size":"Small","desc":"Mel shakes his head slowly. Nikki too.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"It's gone. It was gone the second we landed.\""}],"rect":[67.27,27.88,29.73,20.95]},{"n":5,"size":"Medium","desc":"Hal's voice cracks. Nikki puts a stiff hand on his shoulder. She does not take her hand away.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"I want to go home. I want my mom.\""},{"k":"say","who":"Nikki","mod":"","t":"\"Don't cry. It's annoying.\""}],"rect":[3.0,50.44,64.12,46.56]},{"n":6,"size":"Small","desc":"Jeff watches them. He smiles a little.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"We'll find a way. Together.\""}],"rect":[69.52,50.44,27.48,46.56]}]},{"n":44,"title":"The necklace","splash":false,"layout":"large panel on top, two small panels, a medium panel, a wide panel at the bottom.","note":"","panels":[{"n":1,"size":"Large","desc":"Night. Jeff alone at the veranda edge. The river reflects stars, far more of them than at home.","lines":[],"rect":[3.0,3.0,94.0,30.33]},{"n":2,"size":"Small","desc":"A small box opened on a birthday. A man's hands, his face in shadow, putting a necklace in Jeff's palm. (The father's name, look, and what he knows are all OPEN.)","lines":[{"k":"say","who":"Father","mod":"","t":"\"Keep this close, anak. Never take it off.\""}],"rect":[3.0,34.93,45.8,16.06]},{"n":3,"size":"Small","desc":"Jeff, thought:","lines":[{"k":"cap","who":"","mod":"","t":"\"Dad. What did you give me?\""}],"rect":[51.2,34.93,45.8,16.06]},{"n":4,"size":"Medium","desc":"Behind him, footsteps. The elder advisor with a lantern.","lines":[],"rect":[3.0,52.58,94.0,17.84]},{"n":5,"size":"Wide","desc":"The elder, quietly.","lines":[{"k":"say","who":"Elder","mod":"","t":"[Who gave you that?]"},{"k":"say","who":"Jeff","mod":"","t":"\"My father.\""},{"k":"say","who":"Elder","mod":"","t":"[Then he knew what you carry. Do you?]"}],"rect":[3.0,72.02,94.0,24.98]}]},{"n":45,"title":"The warning","splash":false,"layout":"medium panel, small panel, small panel, small panel, a large panel, a small panel.","note":"","panels":[{"n":1,"size":"Medium","desc":"Jeff.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"No.\""},{"k":"say","who":"Elder","mod":"","t":"[Then it woke in my land for a reason.]"}],"rect":[3.0,3.0,94.0,16.06]},{"n":2,"size":"Small","desc":"The elder.","lines":[{"k":"say","who":"Elder","mod":"","t":"[The Sangkapuluan keep ten. Not all of them sleep. Not all of them are friends.]"}],"rect":[3.0,20.66,29.73,16.06]},{"n":3,"size":"Small","desc":"Jeff.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"How do I get home?\""}],"rect":[35.13,20.66,29.73,16.06]},{"n":4,"size":"Small","desc":"The elder.","lines":[{"k":"say","who":"Elder","mod":"","t":"[The door you opened swings one way, child. Until a reason opens it back.]"}],"rect":[67.27,20.66,29.73,16.06]},{"n":5,"size":"Large","desc":"The elder turns to go, his lantern swaying.","lines":[{"k":"say","who":"Elder","mod":"","t":"[Tomorrow, the Rajah will ask something of you.]"}],"rect":[3.0,38.31,94.0,30.33]},{"n":6,"size":"Small","desc":"Jeff, alone with the lantern light, hand closed around the necklace.","lines":[],"rect":[3.0,70.24,94.0,26.76]}]},{"n":46,"title":"Morning","splash":false,"layout":"wide panel, three small panels, a small panel, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"Sunrise on the river. Hal asleep with his arms and legs spread out. Mel curled around the violin. Nikki awake, sitting at the edge, hair loose.","lines":[],"rect":[3.0,3.0,94.0,17.84]},{"n":2,"size":"Small","desc":"Jeff sits down near her.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"Don't say anything.\""}],"rect":[3.0,22.44,29.73,16.06]},{"n":3,"size":"Small","desc":"Nikki.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"I'm still not your friend.\""},{"k":"say","who":"Jeff","mod":"","t":"\"Never said you were.\""}],"rect":[35.13,22.44,29.73,16.06]},{"n":4,"size":"Small","desc":"Nikki, very quietly.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"Thanks. For yesterday. For Hal's glasses.\""},{"k":"say","who":"Jeff","mod":"","t":"\"Tell him.\""},{"k":"say","who":"Nikki","mod":"","t":"\"Never.\""}],"rect":[67.27,22.44,29.73,16.06]},{"n":5,"size":"Small","desc":"Hal, eyes still closed, rolls over.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"I can hear you.\""}],"rect":[3.0,40.1,94.0,12.49]},{"n":6,"size":"Large","desc":"Nikki turns bright red. SFX in the background: \"!!!\" Jeff and Mel, who was awake all along, burst out laughing.","lines":[],"rect":[3.0,54.18,94.0,42.82]}]},{"n":47,"title":"Summoned","splash":false,"layout":"wide panel, two small panels, a medium panel, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"A messenger arrives at the guest house door with two guards.","lines":[],"rect":[3.0,3.0,94.0,17.84]},{"n":2,"size":"Small","desc":"Messenger.","lines":[{"k":"say","who":"Messenger","mod":"","t":"[The Rajah calls the boy with the bright hair.]"}],"rect":[3.0,22.44,45.8,14.27]},{"n":3,"size":"Small","desc":"Jeff.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"He means me. The purple one.\""},{"k":"say","who":"Hal","mod":"","t":"\"You're the bright hair.\""}],"rect":[51.2,22.44,45.8,14.27]},{"n":4,"size":"Medium","desc":"Jeff tucks the necklace into his wrap. Hal grabs his sleeve.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"We go together.\""},{"k":"say","who":"Mel","mod":"","t":"\"Together.\""},{"k":"say","who":"Nikki","mod":"","t":"\"...Fine.\""}],"rect":[3.0,38.31,94.0,17.84]},{"n":5,"size":"Large","desc":"The four walk side by side toward the hall, backlit by the morning sun.","lines":[],"rect":[3.0,57.75,94.0,39.25]}]},{"n":48,"title":"The demand","splash":false,"layout":"wide panel, medium panel, two small panels, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"The hall again. Warriors line the walls. The elder stands to the Rajah's side, his face unreadable.","lines":[],"rect":[3.0,3.0,94.0,17.84]},{"n":2,"size":"Medium","desc":"The Rajah, from his seat.","lines":[{"k":"say","who":"Rajah","mod":"","t":"[Boy. Give me what hangs on your neck.]"}],"rect":[3.0,22.44,94.0,16.06]},{"n":3,"size":"Small","desc":"The court is silent. Warriors tighten their grip on their spears.","lines":[],"rect":[3.0,40.1,45.8,14.27]},{"n":4,"size":"Small","desc":"Jeff does not move.","lines":[],"rect":[51.2,40.1,45.8,14.27]},{"n":5,"size":"Large","desc":"The Rajah rises, one step down from the dais.","lines":[{"k":"say","who":"Rajah","mod":"","t":"[It is not a request.]"}],"rect":[3.0,55.97,94.0,41.03]}]},{"n":49,"title":"Standing together","splash":false,"layout":"three small panels, a medium panel, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Small","desc":"Hal, whispering.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"Jeff. Just give it.\""}],"rect":[3.0,3.0,29.73,16.34]},{"n":2,"size":"Small","desc":"Mel.","lines":[{"k":"say","who":"Mel","mod":"","t":"\"It's your father's.\""}],"rect":[35.13,3.0,29.73,16.34]},{"n":3,"size":"Small","desc":"Nikki steps up beside Hal without saying a word.","lines":[],"rect":[67.27,3.0,29.73,16.34]},{"n":4,"size":"Medium","desc":"Jeff closes his hand on the necklace. A flash of his father's hands in the flashback box. The elder watches him closely.","lines":[],"rect":[3.0,20.94,94.0,19.98]},{"n":5,"size":"Large","desc":"Jeff takes one step forward, in front of his friends. Same stance as Page 7. Calm smirk. (Spoken in Bisaya, shown here in English.)","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"No, Rajah.\""}],"rect":[3.0,42.52,94.0,54.48]}]},{"n":50,"title":"Chapter ending hook","splash":false,"layout":"a wide panel on top, a medium close up in the middle, a very large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"The hall explodes into motion. Spears rise. The Rajah's eyes narrow.","lines":[{"k":"sfx","who":"","mod":"","t":"!!"}],"rect":[3.0,3.0,94.0,23.61]},{"n":2,"size":"Medium, Close Up","desc":"The necklace begins to hum, the same hum as the bamboo tube. Gold light pours out between Jeff's fingers.","lines":[],"rect":[3.0,28.21,94.0,23.61]},{"n":3,"size":"Very Large","desc":"Jeff stands in front, hair lifted by the light of the necklace. Hal, Mel, and Nikki stand behind him. Golden Baybayin ribbons rise around the four.","lines":[{"k":"cap","who":"","mod":"","t":"\"Hiraya manawari.\""},{"k":"cap","who":"","mod":"","t":"\"To be continued.\""}],"rect":[3.0,53.42,94.0,43.58]}]}];
